// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { motion, useReducedMotion } from "framer-motion";
import { ArrowRight, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";

export interface HeroAction {
  label: string;
  onClick?: () => void;
  href?: string;
  icon?: React.ReactNode;
}

export interface ComponentProps {
  badgeText?: string;
  onBadgeClick?: () => void;
  title: React.ReactNode;
  subtitle: string;
  primaryAction: HeroAction;
  secondaryAction?: HeroAction;
  previewContent?: React.ReactNode;
  footerNote?: string;
  className?: string;
}

export function Component({
  badgeText,
  onBadgeClick,
  title,
  subtitle,
  primaryAction,
  secondaryAction,
  previewContent,
  footerNote,
  className,
}: ComponentProps) {
  const prefersReducedMotion = useReducedMotion();

  const fadeUp = (delay = 0) => ({
    initial: prefersReducedMotion ? { opacity: 0 } : { opacity: 0, y: 18 },
    animate: prefersReducedMotion ? { opacity: 1 } : { opacity: 1, y: 0 },
    transition: {
      duration: prefersReducedMotion ? 0.15 : 0.5,
      delay: prefersReducedMotion ? 0 : delay,
      ease: [0.22, 1, 0.36, 1] as const,
    },
  });

  return (
    <section
      aria-label="Hero Section"
      className={cn(
        "relative w-full overflow-hidden bg-background py-20 md:py-28 lg:py-32 text-foreground",
        className
      )}
    >
      {/* Subtle Grid & Radial Spotlight Background */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 -z-10 flex items-center justify-center"
      >
        <div className="absolute inset-0 bg-[linear-gradient(to_right,hsl(var(--border)/0.45)_1px,transparent_1px),linear-gradient(to_bottom,hsl(var(--border)/0.45)_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_70%_55%_at_50%_0%,#000_65%,transparent_100%)]" />
        <div className="absolute -top-24 h-[340px] w-[620px] rounded-full bg-primary/15 blur-[110px]" />
      </div>

      <div className="mx-auto flex max-w-6xl flex-col items-center px-4 text-center sm:px-6 lg:px-8">
        {/* Announcement Badge */}
        {badgeText && (
          <motion.div {...fadeUp(0)} className="mb-6">
            <button
              type="button"
              onClick={onBadgeClick}
              disabled={!onBadgeClick}
              className={cn(
                "group inline-flex items-center gap-2 rounded-full border border-border bg-muted/60 px-3.5 py-1.5 text-xs font-medium text-foreground backdrop-blur-md transition-colors",
                onBadgeClick
                  ? "cursor-pointer hover:border-primary/40 hover:bg-muted"
                  : "cursor-default"
              )}
            >
              <Sparkles className="size-3.5 text-primary" aria-hidden="true" />
              <span>{badgeText}</span>
              {onBadgeClick && (
                <ArrowRight
                  className="size-3.5 text-muted-foreground transition-transform duration-200 group-hover:translate-x-0.5"
                  aria-hidden="true"
                />
              )}
            </button>
          </motion.div>
        )}

        {/* Headline */}
        <motion.h1
          {...fadeUp(0.08)}
          className="max-w-4xl text-balance text-4xl font-bold tracking-tight sm:text-5xl md:text-6xl lg:leading-[1.1]"
        >
          {title}
        </motion.h1>

        {/* Subheadline */}
        <motion.p
          {...fadeUp(0.16)}
          className="mt-6 max-w-2xl text-pretty text-base text-muted-foreground sm:text-lg md:text-xl"
        >
          {subtitle}
        </motion.p>

        {/* Dual CTA Buttons */}
        <motion.div
          {...fadeUp(0.24)}
          className="mt-8 flex w-full flex-col items-center justify-center gap-3 sm:w-auto sm:flex-row sm:gap-4"
        >
          {primaryAction.href ? (
            <a
              href={primaryAction.href}
              onClick={primaryAction.onClick}
              className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-lg bg-primary px-6 text-sm font-medium text-primary-foreground shadow-sm transition-all hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background sm:w-auto"
            >
              <span>{primaryAction.label}</span>
              {primaryAction.icon ?? <ArrowRight className="size-4" aria-hidden="true" />}
            </a>
          ) : (
            <button
              type="button"
              onClick={primaryAction.onClick}
              className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-lg bg-primary px-6 text-sm font-medium text-primary-foreground shadow-sm transition-all hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background sm:w-auto"
            >
              <span>{primaryAction.label}</span>
              {primaryAction.icon ?? <ArrowRight className="size-4" aria-hidden="true" />}
            </button>
          )}

          {secondaryAction &&
            (secondaryAction.href ? (
              <a
                href={secondaryAction.href}
                onClick={secondaryAction.onClick}
                className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-lg border border-border bg-background/80 px-6 text-sm font-medium text-foreground backdrop-blur-sm transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background sm:w-auto"
              >
                {secondaryAction.icon}
                <span>{secondaryAction.label}</span>
              </a>
            ) : (
              <button
                type="button"
                onClick={secondaryAction.onClick}
                className="inline-flex h-11 w-full items-center justify-center gap-2 rounded-lg border border-border bg-background/80 px-6 text-sm font-medium text-foreground backdrop-blur-sm transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background sm:w-auto"
              >
                {secondaryAction.icon}
                <span>{secondaryAction.label}</span>
              </button>
            ))}
        </motion.div>

        {/* Optional Micro Footer Note */}
        {footerNote && (
          <motion.p
            {...fadeUp(0.3)}
            className="mt-4 text-xs text-muted-foreground"
          >
            {footerNote}
          </motion.p>
        )}

        {/* Glassmorphic Product Preview Container */}
        {previewContent && (
          <motion.div
            {...fadeUp(0.36)}
            className="mt-12 w-full max-w-4xl md:mt-16"
          >
            <div className="relative rounded-2xl border border-border/80 bg-card/60 p-2 shadow-2xl backdrop-blur-xl sm:p-3">
              <div className="overflow-hidden rounded-xl border border-border bg-background">
                {previewContent}
              </div>
            </div>
          </motion.div>
        )}
      </div>
    </section>
  );
}

export default Component;

